Query updateQuery(Query _query)
{
    Query ret = super(_query);

    QueryBuildDataSource qbds = ret.dataSourceTable(tableNum(WMSOrderTrans));
    qbds.addRange(fieldNum(WMSOrderTrans, RouteId)).value(pickingRouteId);

    return ret;
}

public WMSPickingRouteID parmWMSPickingRouteID(WMSPickingRouteID _pickingRouteId = pickingRouteId)
